function cache_fixture_helpers(object_name)
%CACHE_FIXTURE_HELPERS Generate current-schema MATLAB cache fixtures.
    cache_dir = fileparts(mfilename('fullpath'));
    repo_root = pwd;
    fixture_dir = fullfile('tests', 'fixtures');
    addpath(fullfile(repo_root, 'matlab'));

    if exist(cache_dir, 'dir') ~= 7
        mkdir(cache_dir);
    end

    ref = statgen.load_reference(fullfile(fixture_dir, 'reference', 'sharded', '@.bim'));

    switch char(object_name)
        case 'reference'
            statgen.save_reference_cache( ...
                ref, ...
                fullfile(cache_dir, 'reference_matlab_reference_cache_0_1.mat'), ...
                'format', 'v7');
        case 'sumstats'
            panel = statgen.load_sumstats( ...
                fullfile(fixture_dir, 'sumstats', 'traits_complete.tsv.gz'), ...
                ref);
            statgen.save_sumstats_cache( ...
                panel, ...
                fullfile(cache_dir, 'sumstats_matlab_sumstats_cache_0_1.mat'), ...
                'format', 'v7');
        case 'annotations'
            binary = statgen.load_annotations( ...
                {fullfile(fixture_dir, 'annotations', 'anno1.bed'), ...
                 fullfile(fixture_dir, 'annotations', 'anno2.bed')}, ...
                ref);
            continuous = statgen.load_annotation( ...
                fullfile(fixture_dir, 'annotations', 'continuous.annot'), ...
                ref, ...
                'has_header', true, ...
                'value_columns', {'score', 'weight'}, ...
                'annotation_metadata_path', fullfile(fixture_dir, 'annotations', 'continuous.meta'));
            panel = binary.union_annotations(continuous);
            statgen.save_annotations_cache( ...
                panel, ...
                fullfile(cache_dir, 'annotations_matlab_annotations_cache_0_2.mat'), ...
                'format', 'v7');
        case 'genotype'
            ref = statgen.load_reference(fullfile(fixture_dir, 'allele_swaps', 'reference.bim'));
            panel = statgen.load_genotype( ...
                fullfile(fixture_dir, 'allele_swaps', 'genotype', '@'), ...
                ref, 'allow_indel_swaps', true);
            statgen.save_genotype_cache( ...
                panel, ...
                fullfile(cache_dir, 'genotype_matlab_genotype_cache_0_2.mat'), ...
                'format', 'v7');
        otherwise
            error('statgen:cacheFixture', 'unknown cache fixture object: %s', char(object_name));
    end
end
